#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TemperatureCanaryOperation {
    #[doc = "wire value: sidecar_read"]
    SidecarRead,
    #[doc = "wire value: status_read"]
    StatusRead,
    #[doc = "wire value: inference"]
    Inference,
}
impl TemperatureCanaryOperation {
    pub const WIRE_VALUES: &'static [(&'static str, Self)] = &[
        ("sidecar_read", Self::SidecarRead),
        ("status_read", Self::StatusRead),
        ("inference", Self::Inference),
    ];
}

